
const produtos = [
    {id:1, nome:"Brinco Luxo", categoria:"Brincos", preco:29.90, emoji:"💎"},
        {id:2, nome:"Argola Dourada", categoria:"Brincos", preco:19.90, emoji:"✨"},
            {id:3, nome:"Colar Coração", categoria:"Colares", preco:39.90, emoji:"💗"},
                {id:4, nome:"Colar Elegante", categoria:"Colares", preco:45.90, emoji:"📿"},
                    {id:5, nome:"Pulseira Fashion", categoria:"Pulseiras", preco:24.90, emoji:"🌟"},
                        {id:6, nome:"Pulseira Delicada", categoria:"Pulseiras", preco:22.90, emoji:"🌸"},
                            {id:7, nome:"Anel Dourado", categoria:"Anéis", preco:18.90, emoji:"💍"},
                                {id:8, nome:"Anel Luxuoso", categoria:"Anéis", preco:35.90, emoji:"👑"}
                                ];

                                let carrinho = [];
                                let favoritos = [];
                                let categoriaAtual = "Todos";

                                function dinheiro(valor) {
                                    return valor.toLocaleString("pt-BR", {
                                            style: "currency",
                                                    currency: "BRL"
                                                        });
                                                        }

                                                        function filtrar(categoria) {
                                                            categoriaAtual = categoria;
                                                                mostrarProdutos();
                                                                }

                                                                function mostrarProdutos() {
                                                                    const pesquisa = document.getElementById("pesquisa").value.toLowerCase();

                                                                        const filtrados = produtos.filter(p =>
                                                                                p.nome.toLowerCase().includes(pesquisa) &&
                                                                                        (categoriaAtual === "Todos" || p.categoria === categoriaAtual)
                                                                                            );

                                                                                                document.getElementById("lista").innerHTML =
                                                                                                        filtrados.map(p => `
                                                                                                                    <div class="card">
                                                                                                                                    <div class="foto">${p.emoji}</div>
                                                                                                                                                    <h3>${p.nome}</h3>
                                                                                                                                                                    <p class="preco">${dinheiro(p.preco)}</p>
                                                                                                                                                                                    <button onclick="adicionar(${p.id})">
                                                                                                                                                                                                        Comprar
                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                        <button class="favorito" onclick="favoritar(${p.id})">
                                                                                                                                                                                                                                                            ❤️
                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                `).join("") || "<p>Nenhum produto encontrado.</p>";
                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                function adicionar(id) {
                                                                                                                                                                                                                                                                                                    const produto = produtos.find(p => p.id === id);
                                                                                                                                                                                                                                                                                                        const item = carrinho.find(p => p.id === id);

                                                                                                                                                                                                                                                                                                            if (item) {
                                                                                                                                                                                                                                                                                                                    item.quantidade++;
                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                carrinho.push({...produto, quantidade: 1});
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                        atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                            alert("Produto adicionado à sacola!");
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                            function favoritar(id) {
                                                                                                                                                                                                                                                                                                                                                if (favoritos.includes(id)) {
                                                                                                                                                                                                                                                                                                                                                        favoritos = favoritos.filter(item => item !== id);
                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                    favoritos.push(id);
                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                            mostrarFavoritos();
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                            function mostrarFavoritos() {
                                                                                                                                                                                                                                                                                                                                                                                const lista = produtos.filter(p => favoritos.includes(p.id));

                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("listaFavoritos").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                            lista.map(p => `
                                                                                                                                                                                                                                                                                                                                                                                                        <div class="card">
                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="foto">${p.emoji}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <h3>${p.nome}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p class="preco">${dinheiro(p.preco)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onclick="adicionar(${p.id})">Comprar</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onclick="favoritar(${p.id})">❤️ Remover</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `).join("") || "<p>Você ainda não tem favoritos.</p>";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function remover(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                carrinho = carrinho.filter(p => p.id !== id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const area = document.getElementById("itens");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (carrinho.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    area.innerHTML = "Sua sacola está vazia.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                area.innerHTML = carrinho.map(p => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="item">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span>${p.nome} (${p.quantidade})</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span>${dinheiro(p.preco * p.quantidade)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onclick="remover(${p.id})">Excluir</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `).join("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const total = carrinho.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                (soma, p) => soma + p.preco * p.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("total").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Total: " + dinheiro(total);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function irParaLoja() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("loja").scrollIntoView({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            behavior: "smooth"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function finalizar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const nome = document.getElementById("nome").value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!nome || carrinho.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Digite seu nome e escolha um produto!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let mensagem = `Olá! Meu nome é ${nome}. Quero fazer um pedido:\n`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    carrinho.forEach(p => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagem += `\n${p.nome} - ${p.quantidade} unidade(s)`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const total = carrinho.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (soma, p) => soma + p.preco * p.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem += `\nTotal: ${dinheiro(total)}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Substitua pelo número real da loja
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const whatsapp = "5500000000000";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                window.open(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `https://wa.me/${whatsapp}?text=${encodeURIComponent(mensagem)}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "_blank"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarFavoritos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    